export function PingPill({ ms, online = true, class: cls }) {
  const ok = online && Number.isFinite(ms);
  const tier = !ok ? 'off' : ms < 60 ? 'low' : ms < 200 ? 'medium' : 'high';
  const showPath = () => { try { window.__SP_SHELL && window.__SP_SHELL.showPath && window.__SP_SHELL.showPath(ms); } catch (e) { /* shell bridge absent */ } };
  return html`<span class=${cx('ping', `ping--${tier}`, cls)} title=${ok ? `当前延迟 ${ms}ms · 点按查看连接路径` : '未连接'}
    role="button" tabindex="0" onClick=${showPath} onKeyDown=${(e) => { if (e.key === 'Enter' || e.key === ' ') showPath(); }}>

